  "a_sentences": [
    {
      "a_text": "P1 La question litigieuse porte sur la violation du droit fédéral par la juridiction cantonale en admettant un retour à meilleure fortune au titre de l'accident du 9 juillet 2010.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "P2 Pour trancher les prétentions en matière d'assurance-accidents, des bases médicales fiables sont nécessaires.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "P3 La personne assurée se trouve actuellement à la limite de sa capacité de charge en reprenant partiellement son activité professionnelle et en assumant son rôle de père.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "P4 En cas de retour à meilleure fortune ou de séquelles tardives, l'assureur n'est pas lié par la reconnaissance antérieure du lien de causalité naturelle et il incombe à la personne assurée d'établir ce lien avec le degré de la vraisemblance prépondérante.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "P5 Si des doutes, même minimes, subsistent quant à la fiabilité et à la pertinence des constatations médicales internes à l'assureur, une instruction complémentaire doit être ordonnée.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "P6 Le Tribunal fédéral retient qu'admettre un retour à meilleure fortune ne peut être confirmé en l'état, car les avis médicaux divergent et nécessitent une instruction complémentaire.",
      "b_propositions": ["P6"]
    }
  ]
}
